 fun rect(i:Instrumentation,label:String):Rect?{fun walk(n:AccessibilityNodeInfo?):Rect?{if(n==null)return null;if(n.text?.toString()==label||n.contentDescription?.toString()==label)return Rect().also{n.getBoundsInScreen(it)};for(k in 0 until n.childCount)walk(n.getChild(k))?.let{return it};return null};return walk(i.uiAutomation.rootInActiveWindow)?:i.uiAutomation.windows.firstNotNullOfOrNull{walk(it.root)}}
 fun key(i:Instrumentation,code:Int,hold:Long=60){val t=SystemClock.uptimeMillis();i.uiAutomation.injectInputEvent(KeyEvent(t,t,KeyEvent.ACTION_DOWN,code,0),true);Thread.sleep(hold);i.uiAutomation.injectInputEvent(KeyEvent(t,SystemClock.uptimeMillis(),KeyEvent.ACTION_UP,code,0),true);Thread.sleep(200)}
 private fun hold(i:Instrumentation,label:String,mouse:Boolean,ms:Long){val r=rect(i,label)?:error("Missing $label");val t=SystemClock.uptimeMillis();val p=arrayOf(MotionEvent.PointerProperties().apply{id=0;toolType=if(mouse)MotionEvent.TOOL_TYPE_MOUSE else MotionEvent.TOOL_TYPE_FINGER});val c=arrayOf(MotionEvent.PointerCoords().apply{x=r.exactCenterX();y=r.exactCenterY();pressure=1f;size=1f});val src=if(mouse)InputDevice.SOURCE_MOUSE else InputDevice.SOURCE_TOUCHSCREEN
  fun event(action:Int){val e=MotionEvent.obtain(t,SystemClock.uptimeMillis(),action,1,p,c,0,if(mouse&&action==0)MotionEvent.BUTTON_PRIMARY else 0,1f,1f,0,0,src,0);i.uiAutomation.injectInputEvent(e,true);e.recycle()};event(0);Thread.sleep(ms);event(1);Thread.sleep(250)
 }
 fun run(i:Instrumentation,m:PtvModel,a:MainActivity):JSONObject {val out=JSONObject();var clicks=0;var longs=0;val focus=FocusRequester()
  i.runOnMainSync{m.stop();a.setContent{CinemaTheme(false){Column(Modifier.padding(25.dp)){InputButton({clicks++},Modifier.focusRequester(focus),onLongClick={longs++}){Text("长按测试")};LaunchedEffect(Unit){focus.requestFocus()}}}}};Thread.sleep(600)
  hold(i,"长按测试",false,1000);check(clicks==1&&longs==0);hold(i,"长按测试",false,3200);check(longs==1&&clicks==1);hold(i,"长按测试",true,3200);check(longs==2&&clicks==1);i.runOnMainSync{focus.requestFocus()};key(i,KeyEvent.KEYCODE_DPAD_CENTER,3200);check(longs==3&&clicks==1);out.put("touchMouseAndDpadThreeSecondHold",true).put("holdDoesNotAlsoClick",true)
  val w=Work("qa054-ui-episodes","单集标记测试","tv",season=1);val eps=(1..3).map{EpisodeMeta("qa054-$it",1,it,"长度不同的单集标题 $it","","","8.0",200,"")}
  try{i.runOnMainSync{a.setContent{CinemaTheme(false){LazyRow(Modifier.padding(20.dp),horizontalArrangement=Arrangement.spacedBy(12.dp)){items(eps,key={it.id}){EpisodeCard054(m,w,it)}}}}};Thread.sleep(700)
   val bounds=eps.map{rect(i,"单集卡片 ${it.number}")?:error("missing episode")};check(bounds.map{it.top}.distinct().size==1&&bounds.map{it.width()}.distinct().size==1&&bounds.map{it.height()}.distinct().size==1)
   for((label,state)in listOf("已看" to WatchState.COMPLETED,"在看" to WatchState.WATCHING,"想看" to WatchState.PLANNED)){InputQa.clickLabel(i,"第1集观看标记",idle=false);InputQa.clickLabel(i,label,idle=false);UiQa050.await{m.user.episodeMarks[episodeRef(w,1)]?.watchState==state};check(eps.all{rect(i,"单集卡片 ${it.number}")!=null})};val first=rect(i,"单集卡片 1")!!;val marker=rect(i,"第1集观看标记")!!;check(marker.width()<70&&marker.left>first.centerX()&&marker.bottom<=first.bottom+2);check(!InputQa.hasLabel(i,"收藏第1集"));UiQa050.shot(i,"qa054-episode-rail.png");out.put("episodeRailHasUniformCards",true).put("compactRoundMarkerAtBottomRight",true).put("allThreeMarksKeepEveryEpisodeVisible",true)
  }finally{m.db.writableDatabase.delete("episode_flags_v3","k=?",arrayOf(episodeRef(w,1)));m.db.prefs.edit().remove("episode_state_${episodeRef(w,1)}").remove("episode_mark_work_${episodeRef(w,1)}").commit()}
  i.runOnMainSync{m.settingsSection="subtitles";a.setContent{CinemaTheme(false){Settings040(m)}}};Thread.sleep(700);check(!InputQa.hasLabel(i,"展开手机配置 ▾")&&!InputQa.hasLabel(i,"点击扫码"));i.runOnMainSync{m.settingsSection="remote"};Thread.sleep(700);check(InputQa.hasLabel(i,"点击扫码")&&InputQa.hasLabel(i,"备份 / 还原"));out.put("singlePinnedRemotePageWithBackup",true)
  val opened=mutableListOf<String>();val monitor=object:Instrumentation.ActivityMonitor(){override fun onStartActivity(intent:android.content.Intent):Instrumentation.ActivityResult? {if(intent.action==android.content.Intent.ACTION_VIEW&&intent.data?.scheme=="https"){opened+=intent.data.toString();return Instrumentation.ActivityResult(android.app.Activity.RESULT_CANCELED,null)};return null}};i.addMonitor(monitor)
  try{i.runOnMainSync{m.startRemoteConfig("127.0.0.1");a.setContent{CinemaTheme(false){RemoteConfiguration(m)}}};UiQa050.await{m.remoteUrl.isNotBlank()};Thread.sleep(600);InputQa.clickLabel(i,"手机配置配对二维码 · 点击打开浏览器",idle=false);InputQa.clickLabel(i,m.remoteUrl.substringBefore('#'),idle=false);check(opened.size==2&&opened.all{it.contains('#')&&it.endsWith("&page=configuration")});out.put("qrAndLanLinkOpenBrowserWithPairing",true)}finally{i.removeMonitor(monitor);i.runOnMainSync{m.stopRemoteConfig()}}
  i.runOnMainSync{a.setContent{CinemaTheme(false){LiveHub050(m)}}};Thread.sleep(800);val before=m.db.prefs.getString("live_source_order",null);val expected=LiveOrder054.order(LiveParser050.sources(m.db.secrets.read("source_config"),m.db.secrets.read("live_subscription"),m.availableSites.filter{m.siteEnabled(it)}).map{it.key},runCatching{org.json.JSONArray(before?:"[]").objects().map{it.toString()}}.getOrDefault(emptyList()))
  val first=LiveParser050.sources(m.db.secrets.read("source_config"),m.db.secrets.read("live_subscription"),m.availableSites.filter{m.siteEnabled(it)}).firstOrNull{it.key==expected.firstOrNull()}?:error("No live sources");UiQa050.await(45000){InputQa.hasLabel(i,first.name)}
